#include <bits/stdc++.h>
using namespace std;

struct Mod998 {
    static const long long MOD = 998;
    long long add(long long a, long long b) {
        a %= MOD; b %= MOD;
        long long res = a + b;
        if (res >= MOD) res -= MOD;
        return res;
    }
    long long subtract(long long a, long long b) {
        a %= MOD; b %= MOD;
        long long res = a - b;
        if (res < 0) res += MOD;
        return res;
    }
    long long mult(long long a, long long b, long long inv = -1) {
        a %= MOD; b %= MOD;
        long long res = (a * b) % MOD;
        return res;
    }
    long long smallInv(long long a) {
        // Since MOD is prime, use Fermat's little theorem
        return pow_mod(a, MOD - 2);
    }
    long long pow_mod(long long base, long long exp) {
        long long result = 1;
        long long cur = base % MOD;
        while (exp > 0) {
            if (exp & 1) result = (result * cur) % MOD;
            cur = (cur * cur) % MOD;
            exp >>= 1;
        }
        return result;
    }
    long long ncr(int n, int r) {
        static vector<vector<long long>> C(101, vector<long long>(101, -1));
        if (r > n || r < 0) return 0;
        if (n <= 1) return 1;
        if (C[n][r] != -1) return C[n][r];
        C[n][r] = add(ncr(n - 1, r), ncr(n - 1, r - 1));
        return C[n][r];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    Mod998 mod;

    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; p != 0; i++) {
        long long denom = mod.smallInv(n + m - i);
        p = mod.mult(p, n - i, denom);
        phaseSize = mod.add(phaseSize, p);
    }

    long long answer = 0;
    for (int k = 1; k <= n; k++) {
        long long numPhases = mod.mult(m + k, mod.smallInv(k));
        long long term = mod.mult(mod.ncr(n, k), numPhases, phaseSize);
        if ((k & 1) == 1)
            answer = mod.add(answer, term);
        else
            answer = mod.subtract(answer, term);
    }
    cout << answer << "\n";
    return 0;
}

